using System.Net;
using System.Net.Http.Headers;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Infrastructure;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.DependencyInjection.Extensions;
using Sniply.Persistence;
using Xunit;
namespace Sniply.Tests;
public sealed class Factory : WebApplicationFactory<Program> {
 private readonly SqliteConnection connection=new("Data Source=:memory:");
 public string MailDirectory {get;}=Path.Combine(Path.GetTempPath(),"sniply-tests-"+Guid.NewGuid().ToString("N"));
 public Factory(){connection.Open();Environment.SetEnvironmentVariable("Mail__DropDirectory",MailDirectory);Environment.SetEnvironmentVariable("Jwt__Key","isolated-test-key-not-a-production-secret-2026");Environment.SetEnvironmentVariable("ConnectionStrings__Default","Host=unused;Database=unused");Environment.SetEnvironmentVariable("Cookies__Secure","false");}
 protected override void ConfigureWebHost(IWebHostBuilder builder){builder.UseEnvironment("Testing");builder.ConfigureServices(services=>{services.RemoveAll<DbContextOptions<SniplyDb>>();services.RemoveAll<IDbContextOptionsConfiguration<SniplyDb>>();services.AddDbContext<SniplyDb>(o=>o.UseSqlite(connection));using var scope=services.BuildServiceProvider().CreateScope();scope.ServiceProvider.GetRequiredService<SniplyDb>().Database.EnsureCreated();});}
 protected override void Dispose(bool disposing){base.Dispose(disposing);if(disposing){connection.Dispose();if(Directory.Exists(MailDirectory)&&Path.GetFileName(MailDirectory).StartsWith("sniply-tests-"))Directory.Delete(MailDirectory,true);}}
}
public sealed class ApiTests {
 private static async Task<HttpClient> Account(Factory f,string name){var c=f.CreateClient(new(){AllowAutoRedirect=false});var email=name+"@example.test";var r=await c.PostAsJsonAsync("/api/auth/register",new{name,email,password="TestingCode2026",confirmPassword="TestingCode2026"});Assert.Equal(HttpStatusCode.Created,r.StatusCode);var login=await c.PostAsJsonAsync("/api/auth/login",new{email,password="TestingCode2026",rememberMe=true});Assert.Equal(HttpStatusCode.OK,login.StatusCode);var data=await login.Content.ReadFromJsonAsync<JsonElement>();c.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",data.GetProperty("accessToken").GetString());return c;}
 private static object Input(string title="Useful utility",string code="const privateNeedle = true;",Guid[]? groupIds=null)=>new{title,description="A small reusable solution",code,languageId="typescript",categoryId=(Guid?)null,groupIds=groupIds??[]};
 [Fact]public async Task Private_resources_and_groups_cannot_cross_accounts(){using var f=new Factory();using var a=await Account(f,"alice");using var b=await Account(f,"bob");var create=await a.PostAsJsonAsync("/api/snippets",Input());Assert.Equal(HttpStatusCode.Created,create.StatusCode);var s=await create.Content.ReadFromJsonAsync<JsonElement>();var id=s.GetProperty("id").GetGuid();Assert.Equal(HttpStatusCode.NotFound,(await b.GetAsync("/api/snippets/"+id)).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await b.DeleteAsync("/api/snippets/"+id)).StatusCode);var group=await a.PostAsJsonAsync("/api/groups/tag",new{name="private",description=""});var g=await group.Content.ReadFromJsonAsync<JsonElement>();Assert.Equal(HttpStatusCode.BadRequest,(await b.PostAsJsonAsync("/api/snippets",Input(groupIds:[g.GetProperty("id").GetGuid()]))).StatusCode);Assert.Equal(HttpStatusCode.Unauthorized,(await f.CreateClient().GetAsync("/api/snippets")).StatusCode);}
 [Fact]public async Task Search_checks_code_and_pagination_and_validation_are_enforced(){using var f=new Factory();using var c=await Account(f,"searcher");await c.PostAsJsonAsync("/api/snippets",Input());await c.PostAsJsonAsync("/api/snippets",Input("Other","const other = 1;"));var result=await c.GetFromJsonAsync<JsonElement>("/api/snippets?search=privateNeedle&pageSize=1");Assert.Equal(1,result.GetProperty("total").GetInt32());Assert.Equal(1,result.GetProperty("items").GetArrayLength());var page=await c.GetFromJsonAsync<JsonElement>("/api/snippets?pageSize=1&page=2");Assert.Equal(2,page.GetProperty("pages").GetInt32());Assert.Equal(HttpStatusCode.BadRequest,(await c.PostAsJsonAsync("/api/snippets",Input(" "," "))).StatusCode);}
 [Fact]public async Task Sharing_is_explicit_anonymous_and_revocable_without_owner_details(){using var f=new Factory();using var c=await Account(f,"sharer");var r=await c.PostAsJsonAsync("/api/snippets",Input());var s=await r.Content.ReadFromJsonAsync<JsonElement>();var id=s.GetProperty("id").GetGuid();var share=await c.PutAsJsonAsync($"/api/snippets/{id}/share",new{isPublic=true});var data=await share.Content.ReadFromJsonAsync<JsonElement>();var slug=data.GetProperty("publicSlug").GetString();using var guest=f.CreateClient();var content=await guest.GetFromJsonAsync<JsonElement>("/api/public/"+slug);Assert.Equal("Useful utility",content.GetProperty("title").GetString());Assert.False(content.TryGetProperty("userId",out _));Assert.False(content.TryGetProperty("email",out _));Assert.False(content.TryGetProperty("groups",out _));await c.PutAsJsonAsync($"/api/snippets/{id}/share",new{isPublic=false});Assert.Equal(HttpStatusCode.NotFound,(await guest.GetAsync("/api/public/"+slug)).StatusCode);}
 [Fact]public async Task Refresh_rotates_and_logout_revokes_refresh_cookie(){using var f=new Factory();using var c=await Account(f,"session");Assert.Equal(HttpStatusCode.OK,(await c.PostAsync("/api/auth/refresh",null)).StatusCode);Assert.Equal(HttpStatusCode.NoContent,(await c.PostAsync("/api/auth/logout",null)).StatusCode);Assert.Equal(HttpStatusCode.Unauthorized,(await c.PostAsync("/api/auth/refresh",null)).StatusCode);}
 [Fact]public async Task Password_reset_does_not_reveal_account_existence(){using var f=new Factory();using var c=await Account(f,"reset");var known=await c.PostAsJsonAsync("/api/auth/forgot-password",new{email="reset@example.test"});var unknown=await c.PostAsJsonAsync("/api/auth/forgot-password",new{email="unknown@example.test"});Assert.Equal(HttpStatusCode.OK,known.StatusCode);Assert.Equal(await known.Content.ReadAsStringAsync(),await unknown.Content.ReadAsStringAsync());}

 [Fact] public async Task Reset_link_changes_password_once_and_revokes_old_access(){using var f=new Factory();using var c=await Account(f,"recover");await c.PostAsJsonAsync("/api/auth/forgot-password",new{email="recover@example.test"});var message=JsonSerializer.Deserialize<JsonElement>(await File.ReadAllTextAsync(Directory.GetFiles(f.MailDirectory,"*.json").Single()));var url=new Uri(message.GetProperty("Url").GetString()!);var query=Microsoft.AspNetCore.WebUtilities.QueryHelpers.ParseQuery(url.Query);var token=query["token"].ToString();var input=new{email="recover@example.test",token,password="NewTestingCode2026",confirmPassword="NewTestingCode2026"};Assert.Equal(HttpStatusCode.OK,(await c.PostAsJsonAsync("/api/auth/reset-password",input)).StatusCode);Assert.Equal(HttpStatusCode.Unauthorized,(await c.GetAsync("/api/snippets")).StatusCode);Assert.Equal(HttpStatusCode.BadRequest,(await c.PostAsJsonAsync("/api/auth/reset-password",input)).StatusCode);Assert.Equal(HttpStatusCode.Unauthorized,(await c.PostAsJsonAsync("/api/auth/login",new{email="recover@example.test",password="TestingCode2026"})).StatusCode);Assert.Equal(HttpStatusCode.OK,(await c.PostAsJsonAsync("/api/auth/login",new{email="recover@example.test",password="NewTestingCode2026"})).StatusCode);}
 [Fact] public async Task Changing_email_requires_current_password_and_deleting_groups_keeps_snippets(){using var f=new Factory();using var c=await Account(f,"profile");var denied=await c.PutAsJsonAsync("/api/auth/profile",new{name="Profile",email="new@example.test",defaultLanguage="typescript",fontSize=14,wordWrap=true});Assert.Equal(HttpStatusCode.BadRequest,denied.StatusCode);var group=await c.PostAsJsonAsync("/api/groups/collection",new{name="Utilities",description=""});var g=await group.Content.ReadFromJsonAsync<JsonElement>();var id=g.GetProperty("id").GetGuid();var snippet=await c.PostAsJsonAsync("/api/snippets",Input(groupIds:[id]));var item=await snippet.Content.ReadFromJsonAsync<JsonElement>();Assert.Equal(HttpStatusCode.NoContent,(await c.DeleteAsync("/api/groups/collection/"+id)).StatusCode);var saved=await c.GetFromJsonAsync<JsonElement>("/api/snippets/"+item.GetProperty("id").GetGuid());Assert.Equal(0,saved.GetProperty("groups").GetArrayLength());}
}
